  const leadingMatch = /^\s*/.exec(text2);
  const leading = leadingMatch ? leadingMatch[0] : "";
  if (leading.length === text2.length) {
    return { leading: text2, core: "", trailing: "" };
  }
  const rest = text2.slice(leading.length);
  const trailingMatch = /\s*$/.exec(rest);
  const trailing = trailingMatch ? trailingMatch[0] : "";
  const core = rest.slice(0, rest.length - trailing.length);
